{"content":"import glob, os, re, sys, json, datetime

PRINTABLE = set(range(0x20, 0x7F))

def utf16_runs(buf, min_len=6):
    """Yield (offset, text) for runs of printable UTF-16LE characters."""
    i = 0
    n = len(buf)
    while i + 2 <= n:
        cp = buf[i] | (buf[i + 1] << 8)
        ok = cp in PRINTABLE or (0x0400 <= cp <= 0x04FF) or cp in (0x2013, 0x2014, 0x2026, 0x00AB, 0x00BB, 0x2019, 0x201C, 0x201D, 0x00A0, 0x2116, 0x00B0, 0x2192)
        if ok:
            start = i
            chars = []
            while i + 2 <= n:
                cp = buf[i] | (buf[i + 1] << 8)
                if not (cp in PRINTABLE or (0x0400 <= cp <= 0x04FF) or cp in (0x2013, 0x2014, 0x2026, 0x00AB, 0x00BB, 0x2019, 0x201C, 0x201D, 0x00A0, 0x2116, 0x00B0, 0x2192)):
                    break
                chars.append(chr(cp))
                i += 2
            s = ''.join(chars).strip()
            if len(s) >= min_len:
                yield start, s
        else:
            i += 2

URL_RE = re.compile(r'^(https?://|chrome://|about:|file://)')

def extract(path):
    buf = open(path, 'rb').read()
    runs = list(utf16_runs(buf))
    pairs = []
    seen = set()
    for idx, (off, text) in enumerate(runs):
        if not URL_RE.match(text):
            continue
        url = text
        # trim trailing junk
        url = url.split('�')[0].strip()
        if not url or len(url) < 8:
            continue
        title = ''
        for j in range(idx + 1, min(idx + 4, len(runs))):
            cand = runs[j][1]
            if URL_RE.match(cand):
                break
            if len(cand) > 2:
                title = cand
                break
        key = (url, title)
        if key in seen:
            continue
        seen.add(key)
        pairs.append({'url': url, 'title': title, 'offset': off})
    return pairs, len(buf)

def main():
    root = r'C:\Users\spay\AppData\Local\Yandex\YandexBrowser\User Data'
    out = {}
    for prof in ('Default', 'Profile 1', 'Profile 2'):
        sdir = os.path.join(root, prof, 'Sessions')
        if not os.path.isdir(sdir):
            continue
        files = glob.glob(os.path.join(sdir, 'Session_*'))
        if not files:
            out[prof] = {'error': 'no session file'}
            continue
        f = max(files, key=os.path.getmtime)
        try:
            pairs, size = extract(f)
        except PermissionError:
            out[prof] = {'error': 'locked', 'file': f}
            continue
        out[prof] = {
            'file': f,
            'mtime': datetime.datetime.fromtimestamp(os.path.getmtime(f)).isoformat(timespec='seconds'),
            'size': size,
            'unique': len(pairs),
            'tabs': pairs,
        }
    print(json.dumps(out, ensure_ascii=False))

