{"content":"import glob, os, re, json, sqlite3, shutil, tempfile, datetime

PRINTABLE = set(range(0x20, 0x7F))
EXTRA = {0x2013, 0x2014, 0x2026, 0x00AB, 0x00BB, 0x2019, 0x201C, 0x201D, 0x00A0, 0x2116, 0x00B0, 0x2192}
WEB_TIME = 116444736000000000  # microseconds between 1601-01-01 and 1970-01-01


def is_ok(cp):
    return cp in PRINTABLE or (0x0400 <= cp <= 0x04FF) or cp in EXTRA


def utf16_runs(buf, min_len=8):
    i, n = 0, len(buf)
    while i + 2 <= n:
        if is_ok(buf[i] | (buf[i + 1] << 8)):
            chars = []
            while i + 2 <= n and is_ok(buf[i] | (buf[i + 1] << 8)):
                chars.append(chr(buf[i] | (buf[i + 1] << 8)))
                i += 2
            s = ''.join(chars).strip()
            if len(s) >= min_len:
                yield s
        else:
            i += 2


URL_RE = re.compile(r'^https?://[^\s"\'<>|\\^`{}]+$')


def session_urls(path):
    with open(path, 'rb') as f:
        buf = f.read()
    out, seen = [], set()
    for s in utf16_runs(buf):
        s = s.strip()
        if not URL_RE.match(s):
            continue
        # cut obvious trailing binary bleed
        while s and (s[-1] in ',;)]}' or ord(s[-1]) < 0x20):
            s = s[:-1]
        if s in seen or len(s) < 10:
            continue
        seen.add(s)
        out.append(s)
    return out


def history_map(profile_dir):
    hist = os.path.join(profile_dir, 'History')
    if not os.path.isfile(hist):
        return {}
    tmpd = tempfile.mkdtemp(prefix='ybhist')
    dst = os.path.join(tmpd, 'History')
    try:
        shutil.copy2(hist, dst)
    except Exception:
        return {}
    for extra in ('History-wal', 'History-journal', 'History-shm'):
        p = os.path.join(profile_dir, extra)
        if os.path.isfile(p):
            try:
                shutil.copy2(p, os.path.join(tmpd, extra))
            except Exception:
                pass
    con = sqlite3.connect(dst)
    cur = con.cursor()
    m = {}
    try:
        cur.execute('SELECT url, title, last_visit_time FROM urls')
        for url, title, lvt in cur.fetchall():
            if url and url not in m:
                m[url] = (title or '', lvt or 0)
    except Exception as e:
        print('history query failed:', e, file=__import__('sys').stderr)
    con.close()
    shutil.rmtree(tmpd, ignore_errors=True)
    return m


def main():
    root = r'C:\Users\spay\AppData\Local\Yandex\YandexBrowser\User Data'
    out = {}
    for prof in ('Default', 'Profile 1', 'Profile 2'):
        sdir = os.path.join(root, prof, 'Sessions')
        if not os.path.isdir(sdir):
            continue
        files = glob.glob(os.path.join(sdir, 'Session_*'))
        if not files:
            continue
        f = max(files, key=os.path.getmtime)
        try:
            urls = session_urls(f)
        except PermissionError:
            out[prof] = {'error': 'session file locked'}
            continue
        hmap = history_map(os.path.join(root, prof))
        rows = []
        for u in urls:
            t, lvt = hmap.get(u, ('', 0))
            rows.append({'url': u, 'title': t, 'visit': lvt})
        rows.sort(key=lambda r: -r['visit'])
        out[prof] = {
            'file': f,
            'mtime': datetime.datetime.fromtimestamp(os.path.getmtime(f)).isoformat(timespec='seconds'),
            'urls': len(urls),
            'history_index': len(hmap),
            'with_title': sum(1 for r in rows if r['title']),
            'tabs': rows,
        }
    print(json.dumps(out, ensure_ascii=False))


if __name__ == '__main__':
    main()","path":"C:\Users\spay\AppData\Local\Temp\join_tabs.py"}

